select av.sec_uid, avd.suggest_trade_id as trade_id from tb_anchor_video av inner join tb_anchor_video_detail avd on av.video_id = avd.video_id where av.is_deleted = 0 AND av.analysis_status = 2 AND avd.suggest_trade_id is not null AND av.sec_uid in
#{item}
group by av.sec_uid,avd.suggest_trade_id
